package de.sebaro_ventures.design.designsystem

import androidx.compose.material3.Icon
import androidx.compose.runtime.Composable
import androidx.compose.runtime.remember
import androidx.compose.ui.Modifier
import androidx.compose.ui.platform.LocalContext
import androidx.compose.ui.res.painterResource
import de.sebaro_ventures.design.SebaroProduct

/** Bare symbol resource exported beside the complete tiles. */
@Composable
fun SbStartSymbol(product: SebaroProduct, modifier: Modifier = Modifier) {
    val context = LocalContext.current
    val id = remember(product) { context.resources.getIdentifier("sb_symbol_" + product.id.replace('-', '_'), "drawable", context.packageName) }
    require(id != 0) { "Missing product symbol resource; re-export with --product" }
    Icon(painterResource(id), null, modifier, tint = product.tile.glyph)
}
